import { defineComponent } from 'vue';
import { PrizeLeagueManager } from '../../../services/prize-league/prize-league-manager';
import { ITournamentHistoryEntry } from '../../../services/prize-league/types';
import { getPrizeLeagueManager, formatDate } from '../prize-league-utils';
import { inversifyContainer } from '../../../inversify/container';

export default defineComponent({
    name: 'TournamentHistory',
    components: {
    },
    props: {
        visible: {
            type: Boolean,
            default: true
        }
    },
    computed: {
        prizeLeagueManager(): PrizeLeagueManager {
            return getPrizeLeagueManager();
        },
        translations() {
            return inversifyContainer.strings.prizeLeague;
        },
        tournamentHistory(): ITournamentHistoryEntry[] {
            return this.prizeLeagueManager.tournamentHistory.value;
        }
    },
    emits: ['change-panel'],
    methods: {
        getPrizeText(entry: ITournamentHistoryEntry): string {
            const prize = entry.prizes.find(p => p.position === entry.user.position);
            return prize ? prize.displayText : this.translations.history.noPrize;
        },
        formatDate(dateString: string): string {
            return formatDate(dateString);
        },
        onBackClicked() {
            this.$emit('change-panel', 'tournamentList');
        }
    }
});
